    // MARK: - After the foster child's arm

    static let babysittingBurn = followUp(
        key: "story.followup.babysittingBurn", category: .family,
        headlines: ["Child Burned While Being Babysat, Parent Says", "Former Foster Parent Charged in Toddler's Burn"],
        law: "childAbuseMisd", threshold: 5, spec: "Being the caretaker of {V}, a child under 16, inflicted physical injury, a burn to the hand, by other than accidental means, on {DATE}.", ages: 32...62, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} began babysitting a neighbor's two-year-old, {V}, three days a week. On {DATE}, the parent picked {V} up and found a blistered burn across the back of {V.his} right hand. {DL} said {V} touched a pan on the stove. The pediatrician says the burn's straight edge and the unburned palm fit a hand held against something hot, not a child grabbing a pan.",
        state: [E(.document, 3, "Pediatrician's Report", "A second-degree burn across the back of the hand with a straight edge; the palm is untouched."),
                E(.document, 2, "Timeline", "{D} didn't mention the burn until the parent saw it at pickup, five hours later.")],
        defense: [E(.statement, 1, "The Stove", "{DL} says {V} reached up while {D.he} was cooking and the pan handle swung.")],
        witnessRole: "Sheriff's investigator, crimes against children",
        exam: [.direct("What does the burn show?", "\"The back of the hand, a straight edge, and an untouched palm. A child who grabs a pan burns the palm.\""),
               .direct("When did {DL} report it?", "\"{D.He} didn't. The parent found it at pickup, five hours later.\""),
               .direct("What did you find when you examined {V}?", "\"A blistered second-degree burn across the back of {V}'s right hand, with a straight edge. The palm was untouched.\""),
               .direct("What did the pediatrician say about the pattern?", "\"A child who grabs a hot pan burns the palm and fingers. A burn across the back of the hand, with a straight edge, suggests the hand was pressed against something flat.\""),
               .direct("When did {DL} tell the parent?", "\"{D.He} did not. The parent found the burn at pickup, five hours after it happened, when {V} cried as the glove came off.\""),
               .direct("What did {DL} say happened?", "\"That {V} touched a pan on the stove. {D.He} said it happened in a second while {D.he} was cooking.\""),
               .cross("A pan handle can swing into the back of a hand.", "\"The doctor says the edge is too straight for that.\""),
               .cross("Nobody saw what happened.", "\"No one but {DL}. No other person saw what happened.\""),
               .cross("No one saw what happened?", "\"No one but {DL} and {V}. {V} is two years old and cannot say.\""),
               .cross("The parent's nanny camera recorded something?", "\"It did, and I understand it was checked later. I cannot tell you what it recorded because I did not see it before today.\""),
                    .cross("You cannot say what {V}'s hand touched?", "\"The pediatrician says a flat, hot surface with a straight edge. That could be a stove top or an oven door, and I cannot say which.\"")],
        theory: ("A two-year-old's hand was held against something hot, and {D} said nothing until the parent saw it.", "An accident at the stove; the State has a theory, not a witness."),
        allocution: "\"{V} reached for the pan on the stove, and it all happened in a second. I was standing right there, and I'm devastated that {V.he} was hurt. I should have turned the handle in or kept {V.him} farther from the stove. I loved looking after {V.him}, and I'm so sorry for the pain and for the parent's fear.\"",
        truths: ("The parent's nanny camera, checked later, recorded {DL} pressing {V}'s hand to the oven door while {V} cried.",
                 "The parent's nanny camera recorded {V} reaching up and pulling the pan handle while {DL} turned to the sink."),
        defendant: [.direct("What happened?", "\"{V} reached for the pan. It happened in a second.\""),
               .direct("Why didn't you call the parent?", "\"I put cold water on it and thought it was minor.\""),
               .direct("How long did you babysit {V}?", "\"About two months, three days a week. {V}'s parent was a neighbor and I wanted to help with childcare.\""),
               .direct("What happened at the stove?", "\"I was cooking, and {V} reached up. {V} touched the pan, and I pulled {V.him} away and ran cold water on {V.his} hand.\""),
               .direct("How was {V} afterward?", "\"{V} cried for a while and then played. I thought everything was fine, and I should have called anyway.\""),
               .direct("What did {V}'s parent say at pickup?", "\"That {V}'s hand was blistered. I told {V.him} it happened at the stove and that I had put cold water on it.\""),
                    .cross("The palm wasn't burned.", "\"I don't know how burns work.\""),
               .cross("After what happened with your foster child, you kept children again.", "\"People needed help. I took children in because someone had to, and I believed I could do it.\""),
               .cross("You did not mention it for five hours.", "\"I know. I was scared, and I told myself it was not serious. I should have said something at once.\""),
               .cross("You did not call the parent.", "\"I did not. I put cold water on it and told myself it was minor, and I should have called at once.\""),
               .cross("The pediatrician says the edge is too straight for a pan handle.", "\"I am not a doctor. I only know that {V} pulled at a pan and I got {V.him} away.\"")],
        openings: ("{D} began babysitting a neighbor's two-year-old, {V}, three days a week. At pickup, {V}'s parent found a blistered burn across the back of {V.his} right hand, with a straight edge, and {D} had said nothing for five hours.", "The defense will say {V} reached up and touched a pan while {D} was cooking, and {D} put the hand under cold water. No one saw what happened, and the State has a theory, not a witness."),
        closings: ("The burn is on the back of the hand with a straight edge and an untouched palm, the pediatrician says a grabbed pan does not do that, and {D} told no one for five hours. {PRIOR} had already brought {D} before this court once.", "An accident at a stove happens in a second, and no one saw what happened. {D} put cold water on the burn, and the State must prove {D} held the hand against something hot."),
        timeline: [(0, "Midday: {V} burned; 5 p.m.: parent finds the burn at pickup."), (1, "Pediatrician's exam.")],
        identified: "{DL} was the only adult with {V}.",
        impact: "\"My baby screams whenever anyone turns on the stove now. I picked up my little one and found a blistered burn across the back of the hand. I trusted this person with my child three days a week, and I will never be able to forget what I saw.\"")

    static let socialWorkerThreat = followUp(
        key: "story.followup.socialWorkerThreat", category: .publicOrder,
        headlines: ["Social Worker Says Former Foster Parent Made Threats", "Threat Charge Follows Foster License Revocation"],
        law: "communicatingThreats", threshold: 5, spec: "Willfully threatened to physically injure {V}, a DSS social worker, in a manner a reasonable person would believe would be carried out, on {DATE}.", ages: 32...62, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the county revoked {D}'s foster care license. On {DATE}, {DL} waited in the DSS parking lot for {V}, the social worker on the case, and said, \"You took my family. I know where you live. You'll find out what that feels like.\" A security camera recorded {DL} waiting forty minutes by {V}'s car.",
        state: [E(.video, 3, "Parking Lot Camera", "{D} waits forty minutes beside {V}'s car, then steps in front of {V} and points as {V} approaches."),
                E(.statement, 2, "Coworker's Account", "A coworker heard \"you'll find out what that feels like.\"")],
        defense: [E(.statement, 1, "Grief", "{DL} says {D.he} meant {V} would know what losing children feels like someday, not a threat.")],
        witnessRole: "Sheriff's investigator",
        exam: [.direct("What does the camera show?", "\"{DL} waiting forty minutes by {V}'s car, then stepping into {V}'s path and pointing.\""),
               .direct("What did {V} do afterward?", "\"Moved {V.his} kids to a relative's for a week and asked for a deputy at the house.\""),
               .direct("What happened to {DL}'s foster license?", "\"After the earlier case, the county revoked it. {V} was the social worker on that case.\""),
               .direct("What happened in the DSS parking lot?", "\"{DL} waited by {V}'s car, then stepped in front of {V.him} and said, 'You took my family. I know where you live. You'll find out what that feels like.'\""),
               .direct("What did a coworker hear?", "\"A coworker heard 'you'll find out what that feels like.' The coworker called security.\""),
               .direct("How did {V} react to the encounter?", "\"{V} was shaken and went to security right away. {V.He} moved {V.his} kids to a relative's for a week.\""),
               .cross("{DL} never touched {V}.", "\"No. {D.He} never touched {V}, and I'd have noticed if {D.he} had.\""),
               .cross("'You'll find out what that feels like' could mean grief.", "\"With 'I know where you live' in front of it?\""),
               .cross("{DL} was crying at the end, wasn't {D.he}?", "\"{DL}'s pastor arrived moments later and says it ended with {DL} crying. I did not see that part.\""),
               .cross("{DL} drove past {V}'s house?", "\"A neighbor's camera shows {DL} driving past twice that week. {DL} says {D.he} was looking for work nearby.\""),
                    .cross("{DL} did not have a weapon?", "\"No. {D.He} had nothing in {D.his} hands, and {D.he} did not touch {V}.\"")],
        theory: ("{D} waited by a social worker's car and told {V.him} {D.he} knew where {V.he} lived.", "Grief said out loud isn't a threat."),
        allocution: "\"I wanted {V} to see what losing my family did to me, and I said things in that parking lot that I never should have said. I was hurt and angry after my foster license was taken away. I don't want to harm anyone. I'm sorry for frightening {V}, and I'll find another way to be heard.\"",
        truths: ("{DL} had driven past {V}'s house twice that week, a neighbor's camera showed.",
                 "{DL}'s pastor, who arrived moments later, heard the whole exchange and said it ended with {DL} crying, not threatening."),
        defendant: [.direct("Why were you in the parking lot?", "\"I wanted {V.him} to see what {V.he} did to me.\""),
               .direct("What did you mean?", "\"That someday {V.he}'d lose somebody too.\""),
               .direct("What did you mean by 'you took my family'?", "\"The children were taken from my home after the earlier case. I lost my foster license and the kids I loved.\""),
               .direct("Why did you say you knew where {V.he} lived?", "\"Everybody knows where everybody lives here. It was not meant as a threat, and I never went near the house.\""),
               .direct("What do you remember about that afternoon?", "\"I remember crying afterward in the parking lot. My pastor came and sat with me and said I should go home.\""),
               .direct("What did your pastor say afterward?", "\"That I should go home and rest. He sat with me in the parking lot until I stopped crying.\""),
                    .cross("'I know where you live.'", "\"Everybody knows where everybody lives here.\""),
               .cross("You waited forty minutes by {V.his} car.", "\"I wanted to talk. I waited forty minutes by {V.his} car because I didn't know where else to find {V.him}.\""),
               .cross("You drove past {V}'s house twice.", "\"I drive that road to look for work. I did not go there to scare anyone.\""),
               .cross("You stepped in front of {V}.", "\"I did. I wanted {V.him} to look at me. I did not touch {V.him}.\""),
               .cross("You pointed at {V}.", "\"I did, and I was shaking. I was not threatening, though I know how it looked.\"")],
        openings: ("After the county revoked {D}'s foster care license, {D} waited forty minutes in the DSS parking lot beside {V}'s car, stepped in front of {V}, and said, 'You took my family. I know where you live. You'll find out what that feels like.'", "The defense will say {D} was grieving the loss of {D.his} family, wanted {V} to hear {D.him}, and meant only that {V} would someday know what loss feels like. {D} cried when it was over."),
        closings: ("Forty minutes beside a social worker's car, a pointed finger, and the words 'I know where you live.' A neighbor's camera showed {D} driving past {V}'s house twice, and The earlier case, over {PRIOR}, had already shown {D} where this leads.", "{D} lost {D.his} family and said it aloud in grief, and cried when the pastor arrived. The State must prove {D} meant {V} to fear harm and not merely to hear {D.him}."),
        timeline: [(-20, "Foster license revoked."), (0, "Late afternoon: confrontation in the DSS lot.")],
        identified: "The DSS parking lot camera.",
        impact: "\"I sent my children to my sister's for a month after that day in the parking lot. I was told that I'd taken someone's family, and I believed what I heard. I still check the back seat of my car every night before I get in.\"")

    // MARK: - After the dogs

    static let dogsBehindRental = followUp(
        key: "story.followup.dogsBehindRental", category: .publicOrder,
        headlines: ["Scarred Dogs Found Behind New Rental", "Animal Services Seizes Four Dogs, Treadmill From Rental House"],
        law: "animalCruelty", threshold: 6,
        spec: "Maliciously tortured and cruelly treated dogs by keeping them for fighting, on {DATE}.", victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, animal services answered a complaint on {DATE} about dogs crying behind a rental house in {HOOD} where {D} had moved. Officers found four pit bull-type dogs chained out of reach of each other, two with fresh punctures on their faces and front legs, and a carpet-covered treadmill in a carport. {DL} says the dogs belong to a friend {D.he} is keeping them for.",
        state: [E(.physical, 3, "Fresh Wounds", "Two dogs with punctures days old on the face and front legs, treated with veterinary antibiotics no vet prescribed.", .search),
                E(.physical, 2, "Treadmill", "A carpet-covered treadmill and a break stick in the carport.", .search)],
        defense: [E(.statement, 1, "A Friend's Dogs", "{DL} says a friend left the dogs with {D.him} two weeks earlier.")],
        witnessRole: "Animal control officer",
        exam: [.direct("What did you find?", "\"Four dogs chained just out of each other's reach, the way fighting dogs are kept, and a treadmill carpeted so their paws grip.\""),
               .direct("How old were the wounds?", "\"Three or four days. Treated with antibiotics nobody prescribed.\""),
               .direct("What complaint brought animal services to the house?", "\"A neighbor reported dogs crying behind a rental house in {HOOD}, where {DL} had recently moved. We went out the same day.\""), .direct("What did you find in the yard?", "\"Four pit bull-type dogs chained just out of reach of each other, two with fresh punctures on their faces and front legs.\""), .direct("What else was in the carport?", "\"A carpet-covered treadmill and a break stick. Together they are the equipment used to condition fighting dogs.\""), .direct("What treatment had the injured dogs received?", "\"They had been given veterinary antibiotics that no vet had prescribed. Someone had been medicating them at the house.\""),
                    .cross("The dogs may belong to someone else.", "\"{DL} was feeding and medicating them.\""),
               .cross("Did you see a fight?", "\"No. I didn't see a fight, only the aftermath.\""),
                    .cross("{DL} says the dogs belong to a friend?", "\"{D.He} does, and a friend later came forward and admitted they and the treadmill were his. {DL} was the one feeding and medicating them.\""), .cross("You have no video of a fight?", "\"Not at the time. {DL}'s phone later turned up a video from that week of two of the dogs fighting in the carport.\""), .cross("The dogs were hurt when they got loose?", "\"That is what {DL} says. Wounds that fresh, on two dogs, on the face and legs, look like fight wounds to me.\"")],
        theory: ("{D} set up the same yard again: chains, a treadmill, and dogs with fresh fight wounds.", "{D} was keeping a friend's dogs."),
        allocution: "\"Those dogs belong to a friend of mine who is working out of state, and I was only keeping them. I did not fight them, and I did not cause those wounds. I'm sorry that animals were hurt and that I did not look after them better. I'll tell the court every detail about their owner.\"",
        truths: ("{DL}'s phone had a video from that week of two of the dogs fighting in the carport.",
                 "The friend later came forward, admitted the dogs and the treadmill were his, and was charged."),
        defendant: [.direct("Whose dogs are they?", "\"A friend's. He's working out of state.\""),
                    .direct("The treadmill?", "\"His too. The treadmill was also his, along with the rest of what was in there.\""),
                    .direct("How did the dogs come to be at your house?", "\"A friend asked me to keep them for a few weeks while he worked out of state. He brought them, the chains and the treadmill, and said he would be back soon.\""), .direct("What did you do for the dogs?", "\"I fed them and gave them water, and I cleaned the yard. I did not train them, and I did not match them against each other.\""), .direct("Why did the dogs have antibiotics?", "\"I got them from a feed store when two of them came back hurt. I did not think they needed a vet, and I wanted to help.\""), .direct("How were they hurt?", "\"They got loose one night and wandered out, and I found them hurt in the road. I figured they had tangled with each other or with something else.\""),
                    .cross("Who gave them the antibiotics?", "\"I did. They were hurt.\""),
                    .cross("Hurt how?", "\"They got loose and wandered out, and that's how they were hurt.\""),
                    .cross("You know what the treadmill and the break stick are for.", "\"I know now. At the time my friend said it was for exercise, and I did not ask what the stick was.\""), .cross("Your phone had a video of two of them fighting.", "\"They were fighting in the carport one afternoon, and I filmed it because I did not know what to do. I broke it up and I did not show it to anyone.\""), .cross("You set up the same kind of yard after your last case.", "\"It was my friend's yard, not mine. After my last case I should have said no to the whole thing.\"")],
        openings: ("Animal services answered a complaint about dogs crying behind a rental house where {D} had just moved and found four pit bull-type dogs chained out of reach of each other, two with fresh punctures, and a carpeted treadmill and break stick in the carport.", "The defense will say the dogs and the treadmill belonged to a friend who was working out of state, and {D} only fed and medicated them. {D} did not train them or fight them, and a friend later admitted the equipment was his."),
        closings: ("Four chained dogs, two with fresh wounds, antibiotics no vet prescribed, a treadmill and a break stick, and a video of two dogs fighting on {D}'s phone. {D} was back after {PRIOR}.", "The equipment was a friend's, and the friend later admitted it. The State must prove {D} kept the dogs for fighting and not merely that {D} fed them and filmed an accident."),
        timeline: [(0, "Complaint about crying dogs; animal services seizes four dogs.")],
        identified: "The complaint led to {DL}'s rental.",
        doctrines: ["burdenOfProof", "searchSeizure"])

    static let tipsterThreat = followUp(
        key: "story.followup.tipsterThreat", category: .publicOrder,
        headlines: ["Neighbor Who Reported Dogfighting Reports a Threat", "Intimidation Charge After Dog Case"],
        law: "witnessIntimidation", threshold: 6,
        spec: "By threats, attempted to intimidate {V}, a person who had given information to law enforcement, on {DATE}.", victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} came to the door of {V}, a neighbor on Shiloh Road whom {DL} believed had called in the anonymous tip. {V} says {DL} said, \"Snitches end up in the same hole as those dogs.\" {V}'s doorbell camera recorded the visit, with sound.",
        state: [E(.video, 3, "Doorbell Camera", "Audio and video: \"Snitches end up in the same hole as those dogs.\""),
                E(.document, 2, "Tip Record", "Animal services logged the anonymous tip that led to the search.")],
        defense: [E(.statement, 1, "Words, Not Threats", "{DL} says {D.he} was venting and never meant harm.")],
        witnessRole: "Sheriff's investigator",
        exam: [.direct("What's on the doorbell video?", "\"{DL} at {V}'s door: 'Snitches end up in the same hole as those dogs.'\""),
               .direct("Was {V} the tipster?", "\"I can't say who called. What matters is {DL} believed it.\""),
               .direct("What does {DL} say on the video?", "\"'Snitches end up in the same hole as those dogs.' It is clear on the recording, and {V} did not say anything first.\""),
               .direct("Why did {DL} go to {V}'s house?", "\"{DL} believed {V} was the person who had called in the anonymous tip that led to the search. Animal services had logged that tip.\""),
