    static let grandmasCard = followUp(
        key: "story.followup.grandmasCard", category: .whiteCollar,
        headlines: ["ATM Withdrawals From Widow's Account Traced to Grandson", "Grandson in Ring Case Charged With Card Fraud"],
        law: "cardFraud", spec: "Used the debit card of {V}, an older adult, without consent, to withdraw $1,860 in cash, between a month before {DATE} and {DATE}.", ages: 20...40, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, {D}'s grandmother, found eleven ATM withdrawals {V.he} didn't make, $1,860 in all, from {V.his} checking account. ATM cameras at two banks show {DL}. {DL} says {V} lent {D.him} the card for groceries and told {D.him} to take what {D.he} needed.",
        state: [E(.video, 3, "ATM Cameras", "{D} at the machine for nine of the eleven withdrawals."),
                E(.document, 2, "Bank Statement", "Eleven withdrawals of $100 to $300, late at night, over a month.")],
        defense: [E(.statement, 1, "Permission", "{DL} says {V} gave {D.him} the card and PIN for groceries.")],
        witnessRole: "Financial crimes detective",
        exam: [.direct("What do the cameras show?", "\"{DL} at the machine for nine withdrawals, most after midnight.\""),
               .direct("Did {V} give permission?", "\"For groceries, once. Not eleven withdrawals at midnight.\""),
               .direct("How did {V} discover the withdrawals?", "\"{V}, {DL}'s grandmother, reviewed {V.his} checking account statement and found eleven ATM withdrawals {V.he} did not make, $1,860 in all.\""),
               .direct("When were the withdrawals made?", "\"Late at night over about a month. The amounts ran from $100 to $300, and most came after midnight.\""),
               .direct("What did {V} tell you about the card?", "\"That {V.he} gave {DL} the card and PIN once, for one trip to buy groceries. {V.He} never agreed to eleven withdrawals at midnight.\""),
               .direct("What did {V} tell you about {DL}?", "\"That {DL} was a good grandson who helped with groceries. {V} was upset when {V.he} saw the statement.\""),
                    .cross("{V} gave {DL} the PIN.", "\"For one trip to the store.\""),
               .cross("{V}'s memory isn't reliable.", "\"The bank statement's memory is.\""),
               .cross("{V}'s memory could be unreliable, couldn't it?", "\"The bank statement's memory is reliable. It shows eleven withdrawals, nine on camera.\""),
               .cross("{DL} says {V} told {D.him} to take what {D.he} needed?", "\"That is what {DL} says. {V} raised the daily limit for {DL} by phone, according to the bank records, and I do not know what to make of that.\""),
                    .cross("{V} raised the daily limit by phone?", "\"The bank shows {V} called to raise the limit. {V.He} says {V.he} thought it was for one grocery trip.\"")],
        theory: ("{D} drained an older relative's account a few hundred dollars at a time.", "{V} told {D} to take what {D.he} needed."),
        allocution: "\"{V} lent me {V.his} card for groceries, and {V.he} gave me the PIN and told me to take what I needed. I took more than I should have, and I did not keep track. I'm sorry that {V.he} was hurt and that it looked like stealing. I'll pay back every dollar of the eighteen hundred sixty.\"",
        truths: ("{DL}'s texts that month: \"hit the card again tonight.\"", "{V}'s bank records showed {V.he} had raised the daily limit for {DL} by phone."),
        defendant: [.direct("Did {V} give you the card?", "\"Yes. {V} gave me the card and told me the PIN so I could pick things up.\""),
               .direct("For what?", "\"Groceries, and whatever I needed.\""),
               .direct("What was your arrangement with {V}?", "\"My grandmother said I could use her card for groceries and whatever I needed. She gave me the PIN so I could pick up things for her.\""),
               .direct("Why did you use the machines so late?", "\"I work late. My shift ends after midnight, and I went to the machine on my way home from work.\""),
               .direct("What did you spend the money on?", "\"Groceries for her and for me, and some of it on gas. I took what I needed to get through the month.\""),
               .direct("Did she know about the withdrawals?", "\"I thought she did. She raised my limit on the phone, and she never said anything when I brought groceries.\""),
               .cross("Eleven times, after midnight?", "\"I work late. Eleven times after midnight is just my shift schedule.\""),
               .cross("After the ring.", "\"I know how it looks.\""),
               .cross("Your texts say 'hit the card again tonight.'", "\"That is how I talked about it with a friend. I was joking about money, and I did not mean it the way it sounds.\""),
                    .cross("The bank shows eleven withdrawals over a month.", "\"I took money when I needed it. I did not think my grandmother would mind.\""), .cross("She told you to use the card once.", "\"She did, for groceries. After that I kept using it, and I should have asked.\"")],
        openings: ("{V} found eleven ATM withdrawals {V.he} did not make, $1,860 in all, from {V.his} checking account, and ATM cameras at two banks show {D}, {V}'s grandson, at the machine for nine of them, most after midnight. {V} says {V.he} lent the card once for groceries.", "The defense will say {V} gave {D} the card and PIN and told {D} to take what {D.he} needed, and even raised the limit by phone. {D} used the machines on the way home from a late shift."),
        closings: ("Eleven withdrawals over a month, nearly all after midnight, nine on camera, a text saying 'hit the card again tonight,' and an older woman's savings. {D} was back after {PRIOR}.", "A grandmother raised the limit by phone for a grandson who works late. The State must prove {V} did not allow the withdrawals, and a family's loose arrangement is not a theft."),
        timeline: [(-30, "First withdrawal."), (0, "{V} reads the statement and calls the bank.")],
        identified: "ATM cameras.",
        impact: "\"That was my burial money, and I had saved it for years so I wouldn't be a burden to anybody when I go. Eleven times someone took money out of my account, and it was my own grandchild. It breaks my heart more than it empties my purse.\"")

    static let neighborsChainsaw = followUp(
        key: "story.followup.neighborsChainsaw", category: .property,
